using System.Reflection;
namespace ImageGuide;
public static class ReferenceSelfTests
{
    public static void Run()
    {
        int count=0;void Check(string name,Action action){action();count++;Console.WriteLine("PASS "+name);}void Reject(string json){try{PreviewRecipe.Parse(json);}catch(InvalidDataException){return;}throw new Exception("Invalid preview accepted");}
        string empty=PreviewRecipe.Serialize(PreviewRecipe.Empty);
        Check("preview default has no requested mutations",()=>{var value=PreviewRecipe.Parse(empty);if(value.Executable||value.Requested.Length!=0||value.Services.Count!=0)throw new Exception();});
        Check("preview executable true rejected",()=>Reject(empty.Replace("\"Executable\": false","\"Executable\": true")));
        Check("preview arbitrary commands rejected",()=>Reject(empty.Replace("\"Requested\": []","\"Requested\": [], \"Command\": \"anything\"")));
        Check("preview unknown option rejected",()=>Reject(empty.Replace("\"Requested\": []","\"Requested\": [\"unknown\"]")));
        Check("preview duplicate option rejected",()=>Reject(empty.Replace("\"Requested\": []","\"Requested\": [\"tpm\",\"tpm\"]")));
        Check("preview duplicate property rejected",()=>Reject(empty.Replace("\"SchemaVersion\": 1","\"SchemaVersion\": 1, \"SchemaVersion\": 1")));
        Check("preview unknown service rejected",()=>Reject(empty.Replace("\"Services\": {}","\"Services\": {\"UnknownService\":\"Disabled\"}")));
        Check("preview arbitrary startup value rejected",()=>Reject(empty.Replace("\"Services\": {}","\"Services\": {\"Spooler\":\"execute\"}")));
        Check("preview size bound enforced",()=>Reject(new string(' ',65537)));
        Check("preview deterministic roundtrip and diff",()=>{var value=new PreviewRecipe(1,false,["xbox","tpm"],new(){{"Spooler","Manual"}},PreviewRecipe.Regions[1]);string json=PreviewRecipe.Serialize(value);if(PreviewRecipe.Serialize(PreviewRecipe.Parse(json))!=json)throw new Exception();string diff=PreviewRecipe.Diff(PreviewRecipe.Empty,value);if(!diff.Contains("TPM check override: Keep → Requested")||!diff.Contains("Spooler: Unchanged → Manual")||!diff.Contains("no commands"))throw new Exception();});
        var flags=BindingFlags.Instance|BindingFlags.NonPublic;
        GuideForm Form(){var previous=SynchronizationContext.Current;try{return new GuideForm{AutoScaleMode=AutoScaleMode.None,ClientSize=ShellGeometry.CanonicalClient};}finally{SynchronizationContext.SetSynchronizationContext(previous);}}
        Check("preview option service and region undo together",()=>{using var form=Form();var boxes=(Dictionary<string,CheckBox>)typeof(GuideForm).GetField("previewChoices",flags)!.GetValue(form)!;var services=(Dictionary<string,ComboBox>)typeof(GuideForm).GetField("previewServices",flags)!.GetValue(form)!;var region=(ComboBox)typeof(GuideForm).GetField("previewRegion",flags)!.GetValue(form)!;boxes["tpm"].Checked=true;services["Spooler"].SelectedItem="Manual";region.SelectedIndex=1;for(int i=0;i<3;i++)typeof(GuideForm).GetMethod("Undo",flags)!.Invoke(form,null);if(boxes["tpm"].Checked||services["Spooler"].SelectedIndex!=0||region.SelectedIndex!=0)throw new Exception("Preview Undo lost a choice");});
        Check("preview imports cannot mutate while work active",()=>{using var form=Form();typeof(GuideForm).GetField("busy",flags)!.SetValue(form,true);typeof(GuideForm).GetMethod("RefreshActions",flags)!.Invoke(form,null);var controls=(List<Control>)typeof(GuideForm).GetField("recipeMutations",flags)!.GetValue(form)!;if(controls.Any(x=>x.Enabled))throw new Exception("Recipe mutation active during job");});
        Check("source and edition controls share first workspace",()=>{using var form=Form();var pages=(List<TableLayoutPanel>)typeof(GuideForm).GetField("pages",flags)!.GetValue(form)!;bool InPage(Control control){for(Control? c=control;c!=null;c=c.Parent)if(c==pages[0])return true;return false;}if(!InPage((Control)typeof(GuideForm).GetField("source",flags)!.GetValue(form)!)||!InPage((Control)typeof(GuideForm).GetField("editions",flags)!.GetValue(form)!))throw new Exception("Actual controls missing from first workspace");});
        Check("reference preview choices never enable ISO build",()=>{using var form=Form();var boxes=(Dictionary<string,CheckBox>)typeof(GuideForm).GetField("previewChoices",flags)!.GetValue(form)!;foreach(var box in boxes.Values)box.Checked=true;if(((Button)typeof(GuideForm).GetField("build",flags)!.GetValue(form)!).Enabled)throw new Exception("Preview granted execution capability");});
        Check("filtered hardware cards reflow without blank first cell",()=>{using var form=Form();_ = form.Handle;typeof(GuideForm).GetMethod("Go",flags)!.Invoke(form,new object[]{1});var pages=(List<TableLayoutPanel>)typeof(GuideForm).GetField("pages",flags)!.GetValue(form)!;var page=pages[1];var search=page.Controls.OfType<TextBox>().Single();search.Text="secure";var boxes=(Dictionary<string,CheckBox>)typeof(GuideForm).GetField("previewChoices",flags)!.GetValue(form)!;var card=boxes["secure-boot"].Parent!;var grid=(TableLayoutPanel)card.Parent!;if(grid.GetCellPosition(card)!=new TableLayoutPanelCellPosition(0,0))throw new Exception("Filtered result left a blank slot");search.Text="no-such-preview-option";if(!page.Controls.OfType<Label>().Any(x=>x.Text.StartsWith("No preview choices match")))throw new Exception("Empty filter unexplained");});
        Check("header counts service and region preview wishes",()=>{using var form=Form();var services=(Dictionary<string,ComboBox>)typeof(GuideForm).GetField("previewServices",flags)!.GetValue(form)!;services["DiagTrack"].SelectedItem="Manual";var strip=(Label)typeof(GuideForm).GetField("measuredStrip",flags)!.GetValue(form)!;if(!strip.Text.Contains("Preview: 1 requests"))throw new Exception("Service wish omitted");((ComboBox)typeof(GuideForm).GetField("previewRegion",flags)!.GetValue(form)!).SelectedIndex=1;if(!strip.Text.Contains("Preview: 2 requests"))throw new Exception("Region wish omitted");});
        Check("actual build action stays above preview goals and viewport fold",()=>{using var form=Form();_ = form.Handle;typeof(GuideForm).GetMethod("Go",flags)!.Invoke(form,new object[]{9});void Layout(Control c){c.PerformLayout();foreach(Control child in c.Controls)Layout(child);}for(int i=0;i<3;i++)Layout(form);var pages=(List<TableLayoutPanel>)typeof(GuideForm).GetField("pages",flags)!.GetValue(form)!;var viewport=pages[9].Parent!;var build=(Button)typeof(GuideForm).GetField("build",flags)!.GetValue(form)!;var point=Point.Empty;for(Control? control=build;control!=viewport;control=control.Parent){if(control==null)throw new Exception("Build action left viewport hierarchy");point.Offset(control.Left,control.Top);}if(point.Y<0||point.Y+build.Height>viewport.ClientSize.Height||point.X<0||point.X+build.Width>viewport.ClientSize.Width)throw new Exception("Primary build action buried below fold");});
        Console.WriteLine($"{count} reference design and preview safety tests passed.");
    }
}
